    float voronoiBlendSDF(vec3 p, float d1, float d2, float softness) {
        float dist1 = d1;
        float dist2 = d2;

        // Determine which shape is closer
        float closerDist = min(dist1, dist2);
        float fartherDist = max(dist1, dist2);

        // Create a boundary based on the difference
        float boundary = abs(fartherDist - closerDist);

        // Soften the boundary
        return closerDist + smoothstep(0.0, softness, boundary);
    }
    ```

