import 'dart:convert';
import 'dart:io';

void main() {
  // 1. Read the JSON file
  final jsonContent = File('input.json').readAsStringSync();
  final Map<String, dynamic> data = json.decode(jsonContent);

  // 2. Define the class name and properties
  final className = 'User';
  final properties = data.entries.map((e) {
    final key = e.key;
    final value = e.value;
    final type = _inferType(value);
    return '  ${_capitalize(key)}: $type;';
  }).join('\n');

  // 3. Generate the code
  final generatedCode = '''
class $className {
  $properties

  $className.fromJson(Map<String, dynamic> json) {
    return $className(
      ${data.entries.map((e) => '${_capitalize(e.key)}: json['${e.key}']').join(',\n      ')}
    );
  }
}
''';

  // 4. Print or save the result
  print(generatedCode);
  // File('output.dart').writeAsStringSync(generatedCode);
}

String _capitalize(String s) => s[0].toUpperCase() + s.substring(1);

